                    zoom:SetPoint(1, {amount, amount, amount})
                    zoom:SetPoint(2, {amount, amount, amount})
                    zoom:Solve()
                else
                    handler:SetSplineMode("NoteColumnSplineMode_Disabled")
                    zoom_handler:SetSplineMode("NoteColumnSplineMode_Disabled")
