            r#"
local held
return Def.ActorFrame{
    OnCommand=function(self)
        local actor=self:GetChild("Sleeping")
        self:SetUpdateFunction(function()
            local beat=GAMESTATE:GetSongBeat()
            if beat >= .05 and not held then
                held=actor:getaux()
                actor:hibernate(.125)
