            ),
            (
                0,
                vec![block(SongLuaOverlayStateDelta {
                    x: Some(1.0),
                    ..SongLuaOverlayStateDelta::default()
                })],
            ),
        ];
        let to = vec![
            (
                2,
                vec![block(SongLuaOverlayStateDelta {
                    x: Some(30.0),
                    ..SongLuaOverlayStateDelta::default()
                })],
            ),
            (
